echo "Extension installed at:"
echo "  $DEST"

# Copy the path to the clipboard (best effort).
if command -v pbcopy >/dev/null 2>&1; then printf "%s" "$DEST" | pbcopy; COPIED=1;
elif command -v wl-copy >/dev/null 2>&1; then printf "%s" "$DEST" | wl-copy; COPIED=1;
elif command -v xclip >/dev/null 2>&1; then printf "%s" "$DEST" | xclip -selection clipboard; COPIED=1;
else COPIED=0; fi
[ "$COPIED" = 1 ] && echo "  (path copied to your clipboard)"

cat <<STEPS

Next, in Brave or Chrome:
  1. Open  brave://extensions   (or chrome://extensions)
  2. Turn ON 'Developer mode' (top-right toggle)
  3. Click 'Load unpacked'
  4. Paste the path above into the folder box and choose it
  5. Pin 'HR Tool Attendance', click it, sign in with your work email + the
     6-digit code we email you

Shortcuts once connected:
  Alt+Shift+I  = clock in
  Alt+Shift+O  = clock out
STEPS

